// One client for the Future AGI platform, generated from the API contract.
//
//     import { Client } from "@future-agi/sdk";
//     const client = new Client();            // FI_API_KEY / FI_SECRET_KEY / FI_BASE_URL
//     for await (const ds of client.datasets.list()) console.log(ds.name);
//
// Methods under `client.*` are generated by `sdkgen/generate.py` from
// `sdkgen/catalog/operations.yaml`; hand-written additions live in `./resources`.

export { Client } from "./client";
export type { ClientConfig } from "./client";
export {
  APIConnectionError,
  APIError,
  AuthenticationError,
  BadRequestError,
  ConflictError,
  FutureAGIError,
  InternalServerError,
  NotFoundError,
  PaymentRequiredError,
  PermissionDeniedError,
  RateLimitError,
  UnprocessableEntityError,
  WrongRegionError,
} from "./errors";
export { Pager } from "./pagination";
export type { Page } from "./pagination";
export { Resource } from "./resource";
export { Transport } from "./transport";
export type { FileInput, JsonValue, Operation, RequestArgs, RequestOptions } from "./transport";
// The resource classes behind `client.<name>` (subclass them to add methods), their generated base
// classes, every method's `params` type, and the `Resources` map that lists them.
export * from "./resources";
export { UsageOverviewUnavailableError } from "./resources/usage";
// Response models, also importable on their own from "@future-agi/sdk/platform/models".
export * as models from "./models";
